def format_lesson_notes(text):
    headings = {'Introduction', 'Learning goals', 'Characteristics', 'Myths to challenge', 'Global evolution', 'Indian evolution', 'Types', 'Ethiopian application', 'Case study', 'Ecosystem builders and mentors', 'Founding-team design', 'Working agreements', 'Operating rhythm', 'Hiring and partners', 'Ethics and resilience', 'Money model', 'Unit economics', 'Runway and scenarios', 'Funding choices', 'Investor readiness', 'Target and positioning', 'Channel and sales motion', 'Launch loop', 'Pitch structure', 'Capstone', 'Activity', 'Video script', 'Further learning', 'Critical view'}
    output = []
    for raw in text.split('\n\n'):
        lines = [line.strip() for line in raw.splitlines() if line.strip()]
        if not lines:
            continue
        heading = lines[0]
        body = ' '.join(lines[1:])
        if heading in headings:
            if heading == 'Activity':
                output.append(f'<aside class="learning-callout"><strong>Practice activity</strong><p>{escape(body)}</p></aside>')
            elif heading == 'Video script':
                output.append(f'<aside class="learning-callout"><strong>Video lesson guide</strong><p>{escape(body)}</p></aside>')
            elif heading == 'Further learning':
                output.append(f'<p><strong>Further learning:</strong> {escape(body)}</p>')
            else:
                output.append(f'<h2><strong><em>{escape(heading)}</em></strong></h2>')
                if body:
                    output.append(f'<p>{escape(body)}</p>')
        else:
            output.append(f'<p>{escape(" ".join(lines))}</p>')
    return ''.join(output)


