class Command(BaseCommand):
    help = 'Create or refresh the original Startup Fundamentals: From Idea to Launch course.'

    def add_arguments(self, parser):
        parser.add_argument('--instructor', help='Instructor username or numeric user id.')
        parser.add_argument('--dry-run', action='store_true')

    def handle(self, *args, **options):
        instructor = self._get_instructor(options.get('instructor'))
        if any(len(item['questions']) + len(EXTRA_QUESTIONS.get(index, [])) != 10 for index, item in enumerate(LESSONS, start=1)):
            raise CommandError('Every lesson must contain exactly ten questions.')
        if options['dry_run']:
            self.stdout.write(self.style.SUCCESS(f'Validated {len(LESSONS)} lessons and {len(LESSONS) * 10} questions.'))
            return
        with transaction.atomic():
            category, _ = Category.objects.get_or_create(slug='startup', defaults={'name': 'Startup'})
            course, _ = Course.objects.update_or_create(slug='startup-fundamentals-idea-to-launch', defaults={
                'title': 'Startup Fundamentals: From Idea to Launch',
                'subtitle': 'An original, practical 8-week startup-building course',
                'description': 'An original course helping aspiring entrepreneurs move from problem discovery to a tested MVP, responsible funding plan, and launch pitch. Inspired by the public course overview at https://onlinecourses.swayam2.ac.in/e-learning/course/imb26_mg119, but all lesson materials here are newly written for Ethiopian Startup School.',
                'short_description': 'Turn a real customer problem into a tested startup plan.',
                'notes': '<h2>Course study guide</h2><p>Complete one weekly lesson, its activity, and its quiz. The final capstone combines your evidence into a launch-ready portfolio.</p><p><strong>Source note:</strong> The public SWAYAM course page was used only as high-level inspiration for the 8-week topic sequence. This course does not reproduce its videos or lesson text.</p>',
                'notes_enabled': True,
                'learning_objectives': 'Identify and validate customer problems; research markets and competitors; build a Business Model Canvas; design an MVP experiment; plan operations, finance, funding, go-to-market, and a concise pitch.',
                'requirements': 'No prior startup experience required. Access to three potential customer conversations is recommended.',
                'target_audience': 'Students, aspiring founders, innovators, and early-stage business professionals.',
                'tags': 'startup, entrepreneurship, MVP, market research, business model, funding, pitch',
                'instructor': instructor, 'category': category, 'level': Course.Level.BEGINNER,
                'status': Course.Status.PUBLISHED, 'price': 0, 'is_free': True, 'language': 'English', 'duration_hours': 16,
            })
            for order, item in enumerate(LESSONS, start=1):
                section, _ = Section.objects.update_or_create(course=course, order=order, defaults={'title': item['section']})
                lesson, _ = Lesson.objects.update_or_create(section=section, order=1, defaults={
                    'title': item['title'], 'lesson_type': Lesson.LessonType.VIDEO,
                    'content_text': format_lesson_notes(item['notes']), 'video_url': item.get('video_url', ''), 'source_url': item.get('source_url', ''), 'duration_minutes': 60, 'is_preview': order == 1,
                    'is_downloadable': True,
                })
                # The lesson video is the primary video. Admins can add any number
                # of additional Resource records from the lesson admin inline.
                Resource.objects.filter(lesson=lesson, title='Original instructor video').delete()
                quiz, _ = Quiz.objects.update_or_create(lesson=lesson, defaults={
                    'course': course, 'section': section, 'title': f'{item["title"]} Quiz', 'passing_score_percent': 80,
                })
                quiz.questions.all().delete()
                questions = item['questions'] + EXTRA_QUESTIONS.get(order, [])
                for question_order, (question_text, answer, distractors) in enumerate(questions, start=1):
                    question = Question.objects.create(quiz=quiz, text=question_text, question_type=Question.QuestionType.MULTIPLE_CHOICE, order=question_order)
                    answer_choices = build_answer_choices(answer, distractors, question_order)
                    for choice_order, choice_text in enumerate(answer_choices):
                        Choice.objects.create(question=question, text=choice_text, is_correct=choice_text == answer, order=choice_order)
        self.stdout.write(self.style.SUCCESS(f'Created course {course.title} (id={course.id}) with 8 video-script lessons and 80 quiz questions.'))

    def _get_instructor(self, identifier):
        queryset = User.objects.filter(role=User.Role.INSTRUCTOR)
        if identifier:
            try:
                return queryset.get(pk=identifier)
            except (User.DoesNotExist, ValueError):
                user = queryset.filter(username=identifier).first()
                if user:
                    return user
            raise CommandError(f'Instructor not found: {identifier}')
        user = queryset.order_by('id').first()
        if not user:
            raise CommandError('No instructor exists. Create an instructor or pass --instructor.')
        return user
